package com.bananalab.lite;
import java.util.*;import org.json.*;
public final class Stage42ModulesCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}static BananaEngine.Result run(CreatorPersistenceCheck.Fake c,Semilla m,String q)throws Exception{return BananaEngine.run(c,q,new ArrayList<String[]>(),"",true,m);}
 static JSONObject program(JSONObject m)throws Exception{return new JSONObject().put("version",1).put("modules",new JSONArray().put(m));}
 public static void main(String[] args)throws Exception{CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();Semilla m=SemillaCheck.load(args[0]+"/assets/language");run(c,m,"crea a Fito un zorro; agrega una banana llamada Bani");String scene=SceneStore.load(c).json().toString();run(c,m,"prepara ejemplo de modulo");check(RuntimeModules.revision(c)==0&&RuntimeModules.code(c).equals(RuntimeModules.EMPTY)&&SceneStore.load(c).json().toString().equals(scene),"candidate cannot change active code or scene");run(c,m,"prueba modulos");run(c,m,"activa modulos");check(RuntimeModules.revision(c)==1,"test-before-activation creates persistent revision");BananaEngine.Result out=run(c,m,"Fito celebra con Bani");check(out.changed&&out.scene.actions.contains("baila")&&out.scene.actions.contains("saluda")&&out.scene.actions.contains("salta"),"new runtime program changes next real engine request without APK rebuild");
 JSONObject edited=new JSONObject(RuntimeModules.code(c));JSONObject mod=edited.getJSONArray("modules").getJSONObject(0);mod.getJSONArray("steps").getJSONObject(0).put("op","salta");mod.getJSONArray("tests").getJSONObject(0).getJSONArray("actions").put(0,"salta");RuntimeModules.stage(c,edited.toString(),1);RuntimeModules.activate(c);int count=SceneStore.load(c).actions.size();out=run(c,m,"Fito celebra con Bani");check(out.changed&&out.scene.actions.get(count).equals("salta"),"editing actual code changes live semantics");RuntimeModules.rollback(c);count=SceneStore.load(c).actions.size();out=run(c,m,"Fito celebra con Bani");check(out.changed&&out.scene.actions.get(count).equals("baila"),"rollback restores executable behavior");
 run(c,m,"planea: Fito celebra con Bani; continua con Bani saluda");out=run(c,m,"aplica el plan");check(out.changed,"runtime modules integrate with atomic core plans");run(c,m,"planea: Fito celebra con Bani");RuntimeModules.stage(c,RuntimeModules.code(c),RuntimeModules.revision(c));RuntimeModules.activate(c);out=run(c,m,"aplica el plan");check(!out.changed&&out.text.contains("cambió"),"module revision change invalidates a previously prepared plan");int revision=RuntimeModules.revision(c);String active=RuntimeModules.code(c);JSONObject broken=new JSONObject(active);broken.getJSONArray("modules").getJSONObject(0).getJSONArray("tests").getJSONObject(0).getJSONArray("actions").put(0,"gira");RuntimeModules.stage(c,broken.toString(),revision);try{RuntimeModules.activate(c);throw new AssertionError("bad expectation activated");}catch(IllegalArgumentException expected){}check(RuntimeModules.revision(c)==revision&&RuntimeModules.code(c).equals(active),"failed candidate test leaves current revision active");
 try{RuntimeModules.stage(c,active,revision-1);throw new AssertionError("stale stage");}catch(IllegalArgumentException expected){}JSONObject evil=new JSONObject(active);evil.put("eval","delete files");try{new RuntimeProgram(evil.toString());throw new AssertionError("unknown field accepted");}catch(IllegalArgumentException expected){}evil=new JSONObject(active);evil.getJSONArray("modules").getJSONObject(0).getJSONArray("steps").getJSONObject(0).put("op","http");try{new RuntimeProgram(evil.toString());throw new AssertionError("network op accepted");}catch(IllegalArgumentException expected){}
 scene=SceneStore.load(c).json().toString();out=run(c,m,"Fito celebra con Fito");check(!out.changed&&SceneStore.load(c).json().toString().equals(scene),"invalid binding is atomic, not a bad-code rollback");check(RuntimeModules.revision(c)==revision,"domain error does not deactivate valid code");
 CreatorPersistenceCheck.Fake repair=new CreatorPersistenceCheck.Fake();run(repair,m,"crea a Fito un zorro; agrega una banana llamada Bani");out=run(repair,m,"repara este pedido: Fito le de un besito a Bani");check(out.changed&&out.scene.actions.contains("besa")&&RuntimeModules.revision(repair)==1,"local repair compiles, tests, activates and retries same request");String raw=RuntimeModules.code(repair);check(raw.contains("le de un besito")&&raw.contains("steps"),"actual new behavior source persisted");int old=RuntimeModules.revision(repair);out=run(repair,m,"repara este pedido: Fito teletransporta Bani");check(!out.changed&&RuntimeModules.revision(repair)==old,"unsupported repair honestly preserves code");
 CreatorPersistenceCheck.Fake auto=new CreatorPersistenceCheck.Fake();run(auto,m,"crea a Fito un zorro; agrega una banana llamada Bani");out=run(auto,m,"Fito le de un besito a Bani");check(out.changed&&RuntimeModules.revision(auto)==1&&out.text.contains("reparación local"),"ordinary request automatically detects known gap and activates repair");run(auto,m,"pausa reparacion local");check(RuntimeModules.handle(auto,"Fito le da un besito a Bani")==null&&RuntimeModules.revision(auto)==1,"pause prevents new automatic patches but keeps active code");
 CreatorPersistenceCheck.Fake corrupt=new CreatorPersistenceCheck.Fake();RuntimeModules.prefs(corrupt).edit().putString("active","broken-json").commit();out=RuntimeModules.handle(corrupt,"hola");check(out!=null&&!out.changed&&RuntimeModules.code(corrupt).equals(RuntimeModules.EMPTY),"corrupt code recovers motor base without scene changes");
 CreatorPersistenceCheck.Fake fail=new CreatorPersistenceCheck.Fake();RuntimeModules.stage(fail,program(RuntimeModules.example()).toString(),0);fail.fail=true;try{RuntimeModules.activate(fail);throw new AssertionError("failed commit");}catch(java.io.IOException expected){}check(RuntimeModules.revision(fail)==0&&RuntimeModules.code(fail).equals(RuntimeModules.EMPTY),"storage failure cannot half-activate");System.out.println("PASS Stage42 draft isolation, runtime code edits, tests, live activation, rollback, stale guard, domain errors, automatic repair/retry, corruption recovery, storage atomicity and schema boundaries");}
}
